package com.stackgen.metadataservice.entity;
import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="component_events")
public class ComponentEvent { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="component_id",nullable=false) private UUID componentId; @Column(nullable=false,length=30) private String trigger; @Column(nullable=false,length=40) private String action; @Column(name="endpoint_id") private UUID endpointId; @Column(name="target_page_id") private UUID targetPageId; @Column(name="on_success_action",columnDefinition="text") private String onSuccessAction; @Column(name="on_error_action",columnDefinition="text") private String onErrorAction;
 public UUID getId(){return id;} public UUID getComponentId(){return componentId;} public void setComponentId(UUID v){componentId=v;} public String getTrigger(){return trigger;} public void setTrigger(String v){trigger=v;} public String getAction(){return action;} public void setAction(String v){action=v;} public UUID getEndpointId(){return endpointId;} public void setEndpointId(UUID v){endpointId=v;} public UUID getTargetPageId(){return targetPageId;} public void setTargetPageId(UUID v){targetPageId=v;} public String getOnSuccessAction(){return onSuccessAction;} public void setOnSuccessAction(String v){onSuccessAction=v;} public String getOnErrorAction(){return onErrorAction;} public void setOnErrorAction(String v){onErrorAction=v;}
}
